def firstOverflowBooking(bookings, capacity):
    def overflow(k):
        events = []
        for s, e, c in bookings[:k]:
            events.append((s, c))
            events.append((e, -c))
        events.sort()
        load = 0
        for _, d in events:
            load += d
            if load > capacity:
                return True
        return False

    n = len(bookings)
    if not overflow(n):
        return -1
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if overflow(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo - 1
